check!(style_sheets_list, "<style id=a>p{color:red}</style><style id=b media=print>q{}</style><link rel=stylesheet href=/s.css>", "const l=document.styleSheets; console.log(l.length, l[0] instanceof CSSStyleSheet, l[0].ownerNode.id, l.item(1).media.mediaText, l[2].href, l[0].href, l[0].type, l[0].disabled, l[0].cssRules.length, l[0].cssRules[0].selectorText, l[0].cssRules[0].style.color, l[0].cssRules[0].type, l[0].cssRules[0] instanceof CSSStyleRule, l[0].cssRules[0].parentStyleSheet===l[0], l[0].rules===l[0].cssRules||l[0].rules.length===1, l instanceof StyleSheetList, document.getElementById('a').sheet===l[0]);", "3 true a print https://example.test/s.css null text/css false 1 p red 1 true true true true true");
check!(insert_rule_restyles, "<style id=s>#d { color: red }</style><div id=d></div>", "const sh=document.getElementById('s').sheet; const cs=getComputedStyle(document.getElementById('d')); console.log(cs.color); const i=sh.insertRule('#d { color: blue; font-weight: bold }', 1); console.log(i, sh.cssRules.length, cs.color, cs.fontWeight, sh.cssRules[1].cssText); sh.deleteRule(0); console.log(sh.cssRules.length, cs.color); sh.cssRules[0].style.color='green'; console.log(cs.color, sh.cssRules[0].style.cssText); sh.cssRules[0].style.setProperty('color','purple'); sh.cssRules[0].style.removeProperty('font-weight'); console.log(cs.color, cs.fontWeight); sh.cssRules[0].selectorText='#zz'; console.log(cs.color, sh.cssRules[0].selectorText); try { sh.insertRule('#a{}', 9) } catch(e) { console.log(e.name) } try { sh.insertRule('garbage', 0) } catch(e) { console.log(e.name) }", "rgb(255, 0, 0)\n1 2 rgb(0, 0, 255) 700 #d { color: blue; font-weight: bold; }\n1 rgb(0, 0, 255)\nrgb(0, 128, 0) color: green; font-weight: bold;\nrgb(128, 0, 128) 400\nrgb(0, 0, 0) #zz\nIndexSizeError\nSyntaxError");
