check!(constructed_sheets, "<div id=d></div>", "const s=new CSSStyleSheet(); s.replaceSync('#d { color: red }'); console.log(s.cssRules.length, getComputedStyle(d).color, document.adoptedStyleSheets.length); document.adoptedStyleSheets=[s]; console.log(getComputedStyle(d).color, document.adoptedStyleSheets.length, document.adoptedStyleSheets[0]===s); s.replace('#d { color: blue }').then(x=>console.log('replaced', x===s, getComputedStyle(d).color)); s.insertRule('#d { font-size: 40px }'); console.log(getComputedStyle(d).fontSize); s.disabled=true; console.log(getComputedStyle(d).fontSize, s.disabled); s.disabled=false; document.adoptedStyleSheets=[]; console.log(getComputedStyle(d).fontSize); try { document.adoptedStyleSheets=[document.styleSheets[0] || {}] } catch(e) { console.log(e.name) } try { document.styleSheets.length && document.styleSheets[0].replaceSync('') } catch(e) { console.log(e.name) }", "1 rgb(0, 0, 0) 0\nrgb(255, 0, 0) 1 true\n40px\n16px true\n16px\nNotAllowedError\nreplaced true rgb(0, 0, 0)");
